  task automatic request_pause_frame(input [15:0] pause_tv);
    reg [31:0] txctrl;
    begin
      wb_write_reg(`ETH_CTRLMODER_ADR, 32'h0000_0004); // TXFLOW=1
      txctrl = 32'h0;
      txctrl[15:0] = pause_tv;
      txctrl[16] = 1'b1; // TPAUSERQ
      wb_write_reg(`ETH_TX_CTRL_ADR, txctrl);
    end
  endtask

  task automatic rx_send_varied_frames();
    byte fr[];
    int unsigned n;
    begin
      // Good unicast frame to our MAC (00-11-22-33-44-55)
      fr = new[64];
      fr[0] = 8'h00; fr[1] = 8'h11; fr[2] = 8'h22; fr[3] = 8'h33; fr[4] = 8'h44; fr[5] = 8'h55;
      fr[6] = 8'h66; fr[7] = 8'h55; fr[8] = 8'h44; fr[9] = 8'h33; fr[10] = 8'h22; fr[11] = 8'h11;
      fr[12] = 8'h08; fr[13] = 8'h00;
      for(n = 14; n < 64; n++) fr[n] = $urandom_range(0,255);
      mii_send_frame(fr, 64, 1'b1, 1'b1);

      // Bad CRC, short frame (triggers CRC/SF)
      fr = new[20];
      fr[0] = 8'hFF; fr[1] = 8'hFF; fr[2] = 8'hFF; fr[3] = 8'hFF; fr[4] = 8'hFF; fr[5] = 8'hFF;
      for(n = 6; n < 20; n++) fr[n] = $urandom_range(0,255);
      mii_send_frame(fr, 20, 1'b0, 1'b1);

      // Pause control frame to hit RX control frame paths
      fr = new[60];
      fr[0] = 8'h01; fr[1] = 8'h80; fr[2] = 8'hC2; fr[3] = 8'h00; fr[4] = 8'h00; fr[5] = 8'h01;
      fr[6] = 8'h66; fr[7] = 8'h55; fr[8] = 8'h44; fr[9] = 8'h33; fr[10] = 8'h22; fr[11] = 8'h11;
      fr[12] = 8'h88; fr[13] = 8'h08;
      fr[14] = 8'h00; fr[15] = 8'h01;
      fr[16] = 8'h00; fr[17] = 8'h20; // pause time
      for(n = 18; n < 60; n++) fr[n] = 8'h00;
      mii_send_frame(fr, 60, 1'b1, 1'b1);
    end
  endtask

  task automatic tx_inject_collisions();
    int unsigned i;
    begin
      // Create a few collision windows during TX enable
      for(i = 0; i < 2000; i++) begin
        @(posedge mtx_clk_pad_i);
        if(mtxen_pad_o && (i % 37 == 0)) begin
          mcrs_pad_i  <= 1'b1;
          mcoll_pad_i <= 1'b1;
        end else if(i % 37 == 3) begin
          mcoll_pad_i <= 1'b0;
        end else if(i % 37 == 5) begin
          mcrs_pad_i  <= 1'b0;
        end
      end
      mcoll_pad_i <= 1'b0;
      mcrs_pad_i  <= 1'b0;
    end
  endtask

  initial begin
    init_defaults();
    program_basic_regs();

    setup_tx_bds(32'h0000_2000);
    setup_rx_bds(32'h0000_8000);

    // Enable RXFLOW/PASSALL toggles for pause frame behavior coverage
    wb_write_reg(`ETH_CTRLMODER_ADR, 32'h0000_0003); // RXFLOW=1, PASSALL=1

    enable_core(1'b1, 1'b1, 1'b0, 1'b0, 1'b0, 1'b0); // half-duplex, address-checking enabled

    // Run concurrent TX collision injection while also sending RX traffic
    fork
      tx_inject_collisions();
      begin
        repeat(50) @(posedge wb_clk_i);
        rx_send_varied_frames();
      end
      begin
        repeat(200) @(posedge wb_clk_i);
        request_pause_frame($urandom_range(1, 65535));
      end
    join

    // Toggle modes and send again (promiscuous/full duplex/no preamble)
    wb_write_reg(`ETH_CTRLMODER_ADR, 32'h0000_0001); // PASSALL=1
    enable_core(1'b1, 1'b1, 1'b1, 1'b1, 1'b1, 1'b1);
    repeat(100) @(posedge wb_clk_i);
    rx_send_varied_frames();

    repeat(2000) @(posedge wb_clk_i);
    $finish;
  end

