    init_defaults();
    program_basic_regs();

    // Exercise MIIM: write/read/scan with and without preamble
    miim_write_ctrl(5'h01, 5'h00, 16'h1200, 1'b0);
    miim_read_stat(5'h01, 5'h01, 1'b0, miird);
    miim_read_stat(5'h01, 5'h01, 1'b1, miird);
    miim_scan_stat(5'h01, 5'h01);

    // Interrupt mask/source read/clear paths
    wb_write_reg(`ETH_INT_MASK_ADR, 32'h0000_007F);
    wb_read_reg(`ETH_INT_MASK_ADR, tmp);
    wb_read_reg(`ETH_INT_SOURCE_ADR, tmp);
    wb_write_reg(`ETH_INT_SOURCE_ADR, 32'h0000_007F); // clear any set bits

    setup_tx_bds(32'h0000_2000);
    setup_rx_bds(32'h0000_8000);

    // Enable RXFLOW/PASSALL toggles for pause frame behavior coverage
    wb_write_reg(`ETH_CTRLMODER_ADR, 32'h0000_0003); // RXFLOW=1, PASSALL=1

    enable_core(1'b1, 1'b1, 1'b0, 1'b0, 1'b0, 1'b0); // half-duplex, address-checking enabled

    // Run concurrent TX collision injection while also sending RX traffic
    fork
      tx_inject_collisions();
      begin
        repeat(50) @(posedge wb_clk_i);
        rx_send_varied_frames();
      end
      begin
        repeat(200) @(posedge wb_clk_i);
        request_pause_frame($urandom_range(1, 65535));
      end
    join

    // Force MAXFL small and send a too-long frame (TL path)
    wb_write_reg(`ETH_PACKETLEN_ADR, 32'h0040_0080); // MINFL=64, MAXFL=128
    begin
      byte long_fr[];
      long_fr = new[200];
      for(int unsigned i = 0; i < 200; i++) long_fr[i] = $urandom_range(0,255);
      mii_send_frame(long_fr, 200, 1'b0, 1'b1);
    end
    wb_write_reg(`ETH_PACKETLEN_ADR, 32'h0040_0600); // restore

    // Toggle modes and send again (promiscuous/full duplex/no preamble)
    wb_write_reg(`ETH_CTRLMODER_ADR, 32'h0000_0001); // PASSALL=1
    enable_core(1'b1, 1'b1, 1'b1, 1'b1, 1'b1, 1'b1);
    repeat(100) @(posedge wb_clk_i);
    rx_send_varied_frames();

    // Allow time for DMA/writes to complete, and for error-injected master cycles.
    repeat(20000) @(posedge wb_clk_i);
    $finish;
  end

endmodule

